fn prefix_function(bytes: &[u8]) -> Vec<usize> {
    let mut pi = vec![0; bytes.len()];
    for i in 1..bytes.len() {
        let mut j = pi[i - 1];
        while j > 0 && bytes[i] != bytes[j] { j = pi[j - 1]; }
        if bytes[i] == bytes[j] { j += 1; }
        pi[i] = j;
    }
    pi
}

